// Generate proposal document content
const bomData = $input.first().json;
const template = JSON.parse($input.item.json.data.toString());

// Build document sections
const sections = [];

// Title Section
sections.push({
  type: 'title',
  content: `E-rate Equipment Proposal\n${bomData.applicantName}\nApplication #${bomData.applicationNumber}`
});

// Executive Summary
sections.push({
  type: 'heading1',
  content: 'Executive Summary'
});

sections.push({
  type: 'paragraph',
  content: `Converged Networks is pleased to submit this proposal for ${bomData.applicantName}'s E-rate funding application #${bomData.applicationNumber}. We specialize in providing Ruckus, Extreme, and Ubiquiti networking solutions for educational institutions.`
});

// Requirements Summary
sections.push({
  type: 'heading1',
  content: 'Requirements Summary'
});

if (bomData.requirements && bomData.requirements.length > 0) {
  bomData.requirements.forEach(req => {
    sections.push({
      type: 'paragraph',
      content: `• ${req.specifications} - Quantity: ${req.quantity}`
    });
  });
}

// Primary BOM - Ruckus
sections.push({
  type: 'heading1',
  content: 'Primary Recommendation - Ruckus Networks'
});

sections.push({
  type: 'paragraph',
  content: 'We recommend Ruckus Networks equipment for superior performance, reliability, and E-rate compliance.'
});

sections.push({
  type: 'table',
  headers: ['Item', 'Model', 'Part Number', 'Qty', 'Unit Price', 'Total'],
  rows: bomData.bom.primary.map(item => ([
    item.description,
    item.model,
    item.partNumber,
    item.quantity.toString(),
    item.unitPrice,
    'TBD' // Will be filled in with actual pricing
  ]))
});

// Alternative - Extreme Networks
if (bomData.bom.alternative_extreme && bomData.bom.alternative_extreme.length > 0) {
  sections.push({
    type: 'heading1',
    content: 'Alternative Option - Extreme Networks'
  });

  sections.push({
    type: 'table',
    headers: ['Item', 'Model', 'Part Number', 'Qty', 'Unit Price', 'Total'],
    rows: bomData.bom.alternative_extreme.map(item => ([
      item.description,
      item.model,
      item.partNumber,
      item.quantity.toString(),
      item.unitPrice,
      'TBD'
    ]))
  });
}

// Alternative - Ubiquiti
if (bomData.bom.alternative_ubiquiti && bomData.bom.alternative_ubiquiti.length > 0) {
  sections.push({
    type: 'heading1',
    content: 'Alternative Option - Ubiquiti Networks'
  });

  sections.push({
    type: 'table',
    headers: ['Item', 'Model', 'Part Number', 'Qty', 'Unit Price', 'Total'],
    rows: bomData.bom.alternative_ubiquiti.map(item => ([
      item.description,
      item.model,
      item.partNumber,
      item.quantity.toString(),
      item.unitPrice,
      'TBD'
    ]))
  });
}

// AI Recommendations
if (bomData.aiRecommendations) {
  sections.push({
    type: 'heading1',
    content: 'Technical Recommendations'
  });

  sections.push({
    type: 'paragraph',
    content: JSON.stringify(bomData.aiRecommendations, null, 2)
  });
}

// Budget Information
if (bomData.budget) {
  sections.push({
    type: 'heading1',
    content: 'Budget Information'
  });

  sections.push({
    type: 'paragraph',
    content: `Estimated Category 2 Budget: $${bomData.budget}`
  });
}

// Timeline
if (bomData.deadline) {
  sections.push({
    type: 'heading1',
    content: 'Timeline'
  });

  sections.push({
    type: 'paragraph',
    content: `Contract Deadline: ${bomData.deadline}`
  });
}

// Contact Information
sections.push({
  type: 'heading1',
  content: 'Contact Information'
});

sections.push({
  type: 'paragraph',
  content: `Converged Networks\nKevin Duck\nEmail: kevin@convergednetworks.com`
});

return [{
  json: {
    applicationNumber: bomData.applicationNumber,
    applicantName: bomData.applicantName,
    documentTitle: `E-rate Proposal - ${bomData.applicantName} - ${bomData.applicationNumber}`,
    sections: sections,
    bomData: bomData
  }
}];

// Format content for Google Docs API
const sections = $input.item.json.sections;
const documentId = $input.item.json.documentId;

// Convert sections to Google Docs requests
const requests = [];
let index = 1; // Start after title

sections.forEach(section => {
  switch (section.type) {
    case 'heading1':
      requests.push({
        insertText: {
          location: { index: index },
          text: section.content + '\n\n'
        }
      });
      requests.push({
        updateParagraphStyle: {
          range: {
            startIndex: index,
            endIndex: index + section.content.length
          },
          paragraphStyle: {
            namedStyleType: 'HEADING_1'
          },
          fields: 'namedStyleType'
        }
      });
      index += section.content.length + 2;
      break;

    case 'paragraph':
      requests.push({
        insertText: {
          location: { index: index },
          text: section.content + '\n\n'
        }
      });
      index += section.content.length + 2;
      break;

    case 'table':
      // Tables are complex in Google Docs API
      // For now, we'll format as text
      let tableText = section.headers.join('\t') + '\n';
      section.rows.forEach(row => {
        tableText += row.join('\t') + '\n';
      });
      requests.push({
        insertText: {
          location: { index: index },
          text: tableText + '\n'
        }
      });
      index += tableText.length + 1;
      break;
  }
});

return [{
  json: {
    documentId: documentId,
    requests: requests,
    applicationNumber: $input.item.json.applicationNumber,
    bomData: $input.item.json.bomData
  }
}];

// Final output with document link and summary
const documentId = $input.item.json.documentId;
const bomData = $input.item.json.bomData;

return [{
  json: {
    success: true,
    applicationNumber: bomData.applicationNumber,
    applicantName: bomData.applicantName,
    documentId: documentId,
    documentUrl: `https://docs.google.com/document/d/${documentId}/edit`,
    proposalSummary: {
      primaryManufacturer: 'Ruckus',
      itemCount: bomData.bom.primary.length,
      budget: bomData.budget,
      deadline: bomData.deadline
    },
    message: 'Proposal document created successfully. You can now edit pricing and submit.'
  }
}];

